  const fetchApi = getFetch();
  const url = `https://www.crossmint.com/api/v1-alpha1/wallets/${chain}:${walletAddress}/balances`;

  const response = await fetchApi(url, {
    method: "GET",
    headers: {
      "x-api-key": apiKey,
      Accept: "application/json",
    },
  });

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(`Balance request failed (${response.status}): ${errorText}`);
  }

  const data = await response.json();
  let balanceValue = null;

  if (typeof data?.balance === "string") {
    balanceValue = data.balance;
  } else if (Array.isArray(data?.balances) && data.balances.length > 0) {
    balanceValue = data.balances[0]?.amount ?? data.balances[0]?.balance;
  }

  if (balanceValue == null) {
    balanceValue = JSON.stringify(data);
  }

  return {
    success: true,
    walletAddress,
    chain,
    balance: String(balanceValue),
  };
}

