  const fetchApi = getFetch();
  const url = "https://www.crossmint.com/api/2022-06-09/collections/default/nfts";

  const body = {
    recipient: `email:${email}`,
    chain: "polygon-amoy",
    metadata: {
      name: "Purchase Receipt",
      description: `Receipt for purchase ${purchaseId}`,
      attributes: [
        {
          trait_type: "purchaseId",
          value: purchaseId,
        },
      ],
    },
  };

  const response = await fetchApi(url, {
    method: "POST",
    headers: {
      "x-api-key": apiKey,
      "Content-Type": "application/json",
      Accept: "application/json",
    },
    body: JSON.stringify(body),
  });

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(`Mint request failed (${response.status}): ${errorText}`);
  }

  const data = await response.json();
  const actionId = data?.actionId || data?.id || data?.onChain?.actionId;

  if (!actionId) {
    throw new Error("Mint response did not include an actionId.");
  }

  return {
    success: true,
    email,
    purchaseId,
    actionId: String(actionId),
  };
}

const { CrossmintWalletsSDK } = require("@crossmint/wallets-sdk");

let cachedSdk = null;

function getEnv(name) {
  const value = process.env[name];
  if (!value) {
    throw new Error(`Missing required environment variable: ${name}`);
  }
  return value;
}

function getFetch() {
  if (typeof fetch === "function") {
    return fetch;
  }
  try {
    return require("node-fetch");
  } catch (error) {
    throw new Error("Fetch API is not available in this Node.js runtime.");
  }
}

function getWalletsSdk() {
  if (cachedSdk) {
    return cachedSdk;
  }
  const apiKey = getEnv("CROSSMINT_API_KEY");
  const signerSecret = getEnv("SIGNER_SECRET");

  cachedSdk = new CrossmintWalletsSDK({
    apiKey,
    signer: {
      type: "secret",
      secret: signerSecret,
    },
  });

  return cachedSdk;
}

async function createWallet({ userId, chain }) {
  const sdk = getWalletsSdk();
  const walletParams = {
    type: "evm-smart-wallet",
    userId,
    chain,
  };

  let wallet = null;

  if (typeof sdk.createWallet === "function") {
    wallet = await sdk.createWallet(walletParams);
  } else if (typeof sdk.getOrCreateWallet === "function") {
    wallet = await sdk.getOrCreateWallet(walletParams);
  } else if (sdk.wallets && typeof sdk.wallets.create === "function") {
    wallet = await sdk.wallets.create(walletParams);
  } else {
    throw new Error("Crossmint Wallets SDK does not expose a wallet creation method.");
  }

  const address = wallet?.address || wallet?.wallet?.address || wallet?.walletAddress;
  if (!address) {
    throw new Error("Wallet creation response did not include an address.");
  }

  return {
    success: true,
    address,
    chain,
    userId,
  };
}

async function checkBalance({ walletAddress, chain }) {
  const apiKey = getEnv("CROSSMINT_API_KEY");
